create table if not exists users (id serial primary key, name text not null, email text unique not null, password_hash text not null, role text not null check(role in ('business','student_team')), xp integer not null default 0, created_at timestamptz default now());
create table if not exists tasks (id serial primary key, owner_id integer references users(id), title text not null, industry text, context text, data text, expected_result text, success_criteria text, constraints text, users text, contact text, interaction_format text, score integer not null default 0, published boolean default false, created_at timestamptz default now());
create table if not exists proposals (id serial primary key, task_id integer references tasks(id) on delete cascade, team_id integer references users(id), idea text not null, plan text, timeline text, prototype_url text, status text not null default 'pending', created_at timestamptz default now());
create table if not exists messages (id serial primary key, task_id integer references tasks(id) on delete cascade, sender_id integer references users(id), body text not null, created_at timestamptz default now());
